-- RC50.88: RH360, folha e Portal do Servidor multi-tenant e multi-esfera.
-- Aditiva, idempotente; integrações externas somente mediante adaptador contratado.
CREATE SCHEMA IF NOT EXISTS sigov;

CREATE TABLE IF NOT EXISTS sigov.rh_servidor (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 tenant_id bigint NOT NULL, entidade_id bigint NOT NULL, exercicio_id bigint,
 esfera_governo varchar(12) NOT NULL, tipo_entidade varchar(40) NOT NULL, orgao_superior_id bigint, orgao_id bigint,
 unidade_gestora_id bigint, unidade_executora_id bigint, hierarquia_administrativa varchar(200),
 abrangencia_territorial varchar(160), uf char(2), municipio varchar(160), regiao varchar(120), jurisdicao varchar(160),
 status varchar(30) NOT NULL DEFAULT 'ativo', ativo boolean NOT NULL DEFAULT true, is_deleted boolean NOT NULL DEFAULT false, dados jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by bigint, updated_by bigint,
 CHECK (esfera_governo IN ('municipal','estadual','federal')), CHECK (length(trim(tipo_entidade)) > 0), CHECK (status <> ''), cpf_hash char(64) NOT NULL, nome varchar(200) NOT NULL, CHECK (cpf_hash ~ '^[0-9a-f]{64}$')
);
ALTER TABLE sigov.rh_servidor
 ADD COLUMN IF NOT EXISTS entidade_id bigint NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exercicio_id bigint,
 ADD COLUMN IF NOT EXISTS orgao_id bigint, ADD COLUMN IF NOT EXISTS unidade_gestora_id bigint, ADD COLUMN IF NOT EXISTS unidade_executora_id bigint,
 ADD COLUMN IF NOT EXISTS status varchar(30) NOT NULL DEFAULT 'ativo', ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true,
 ADD COLUMN IF NOT EXISTS is_deleted boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS ix_rh_servidor_contexto ON sigov.rh_servidor(tenant_id, entidade_id, exercicio_id, orgao_id, unidade_gestora_id, unidade_executora_id, status);
CREATE TABLE IF NOT EXISTS sigov.rh_servidor_documento (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 tenant_id bigint NOT NULL, entidade_id bigint NOT NULL, exercicio_id bigint,
 esfera_governo varchar(12) NOT NULL, tipo_entidade varchar(40) NOT NULL, orgao_superior_id bigint, orgao_id bigint,
 unidade_gestora_id bigint, unidade_executora_id bigint, hierarquia_administrativa varchar(200),
 abrangencia_territorial varchar(160), uf char(2), municipio varchar(160), regiao varchar(120), jurisdicao varchar(160),
 status varchar(30) NOT NULL DEFAULT 'ativo', ativo boolean NOT NULL DEFAULT true, is_deleted boolean NOT NULL DEFAULT false, dados jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by bigint, updated_by bigint,
 CHECK (esfera_governo IN ('municipal','estadual','federal')), CHECK (length(trim(tipo_entidade)) > 0), CHECK (status <> '')
);
ALTER TABLE sigov.rh_servidor_documento
 ADD COLUMN IF NOT EXISTS entidade_id bigint NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exercicio_id bigint,
 ADD COLUMN IF NOT EXISTS orgao_id bigint, ADD COLUMN IF NOT EXISTS unidade_gestora_id bigint, ADD COLUMN IF NOT EXISTS unidade_executora_id bigint,
 ADD COLUMN IF NOT EXISTS status varchar(30) NOT NULL DEFAULT 'ativo', ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true,
 ADD COLUMN IF NOT EXISTS is_deleted boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS ix_rh_servidor_documento_contexto ON sigov.rh_servidor_documento(tenant_id, entidade_id, exercicio_id, orgao_id, unidade_gestora_id, unidade_executora_id, status);
CREATE TABLE IF NOT EXISTS sigov.rh_vinculo_funcional (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 tenant_id bigint NOT NULL, entidade_id bigint NOT NULL, exercicio_id bigint,
 esfera_governo varchar(12) NOT NULL, tipo_entidade varchar(40) NOT NULL, orgao_superior_id bigint, orgao_id bigint,
 unidade_gestora_id bigint, unidade_executora_id bigint, hierarquia_administrativa varchar(200),
 abrangencia_territorial varchar(160), uf char(2), municipio varchar(160), regiao varchar(120), jurisdicao varchar(160),
 status varchar(30) NOT NULL DEFAULT 'ativo', ativo boolean NOT NULL DEFAULT true, is_deleted boolean NOT NULL DEFAULT false, dados jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by bigint, updated_by bigint,
 CHECK (esfera_governo IN ('municipal','estadual','federal')), CHECK (length(trim(tipo_entidade)) > 0), CHECK (status <> ''), servidor_id bigint NOT NULL REFERENCES sigov.rh_servidor(id), matricula varchar(40) NOT NULL, tipo_vinculo varchar(30) NOT NULL, cargo_id bigint, data_admissao date NOT NULL, data_desligamento date, CHECK (tipo_vinculo IN ('efetivo','comissionado','temporario','celetista','agente_politico','estagiario','terceirizado','pensionista','aposentado','outro')), CHECK (data_desligamento IS NULL OR data_desligamento >= data_admissao)
);
ALTER TABLE sigov.rh_vinculo_funcional
 ADD COLUMN IF NOT EXISTS entidade_id bigint NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exercicio_id bigint,
 ADD COLUMN IF NOT EXISTS orgao_id bigint, ADD COLUMN IF NOT EXISTS unidade_gestora_id bigint, ADD COLUMN IF NOT EXISTS unidade_executora_id bigint,
 ADD COLUMN IF NOT EXISTS status varchar(30) NOT NULL DEFAULT 'ativo', ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true,
 ADD COLUMN IF NOT EXISTS is_deleted boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS ix_rh_vinculo_funcional_contexto ON sigov.rh_vinculo_funcional(tenant_id, entidade_id, exercicio_id, orgao_id, unidade_gestora_id, unidade_executora_id, status);
