 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by bigint, updated_by bigint,
 CHECK (esfera_governo IN ('municipal','estadual','federal')), CHECK (length(trim(tipo_entidade)) > 0), CHECK (status <> ''), servidor_id bigint NOT NULL REFERENCES sigov.rh_servidor(id), valor_parcela numeric(18,2) NOT NULL, margem_percentual numeric(7,4), CHECK (valor_parcela >= 0), CHECK (margem_percentual IS NULL OR margem_percentual BETWEEN 0 AND 100)
);
ALTER TABLE sigov.rh_consignacao
 ADD COLUMN IF NOT EXISTS entidade_id bigint NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exercicio_id bigint,
 ADD COLUMN IF NOT EXISTS orgao_id bigint, ADD COLUMN IF NOT EXISTS unidade_gestora_id bigint, ADD COLUMN IF NOT EXISTS unidade_executora_id bigint,
 ADD COLUMN IF NOT EXISTS status varchar(30) NOT NULL DEFAULT 'ativo', ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true,
 ADD COLUMN IF NOT EXISTS is_deleted boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS ix_rh_consignacao_contexto ON sigov.rh_consignacao(tenant_id, entidade_id, exercicio_id, orgao_id, unidade_gestora_id, unidade_executora_id, status);
CREATE TABLE IF NOT EXISTS sigov.rh_auditoria_sensivel (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 tenant_id bigint NOT NULL, entidade_id bigint NOT NULL, exercicio_id bigint,
 esfera_governo varchar(12) NOT NULL, tipo_entidade varchar(40) NOT NULL, orgao_superior_id bigint, orgao_id bigint,
 unidade_gestora_id bigint, unidade_executora_id bigint, hierarquia_administrativa varchar(200),
 abrangencia_territorial varchar(160), uf char(2), municipio varchar(160), regiao varchar(120), jurisdicao varchar(160),
 status varchar(30) NOT NULL DEFAULT 'ativo', ativo boolean NOT NULL DEFAULT true, is_deleted boolean NOT NULL DEFAULT false, dados jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by bigint, updated_by bigint,
 CHECK (esfera_governo IN ('municipal','estadual','federal')), CHECK (length(trim(tipo_entidade)) > 0), CHECK (status <> ''), servidor_id bigint REFERENCES sigov.rh_servidor(id), operacao varchar(30) NOT NULL, recurso varchar(120) NOT NULL, finalidade text NOT NULL, ip_hash char(64)
);
ALTER TABLE sigov.rh_auditoria_sensivel
 ADD COLUMN IF NOT EXISTS entidade_id bigint NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exercicio_id bigint,
 ADD COLUMN IF NOT EXISTS orgao_id bigint, ADD COLUMN IF NOT EXISTS unidade_gestora_id bigint, ADD COLUMN IF NOT EXISTS unidade_executora_id bigint,
 ADD COLUMN IF NOT EXISTS status varchar(30) NOT NULL DEFAULT 'ativo', ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true,
 ADD COLUMN IF NOT EXISTS is_deleted boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS ix_rh_auditoria_sensivel_contexto ON sigov.rh_auditoria_sensivel(tenant_id, entidade_id, exercicio_id, orgao_id, unidade_gestora_id, unidade_executora_id, status);
ALTER TABLE sigov.rh_servidor ADD COLUMN IF NOT EXISTS cpf_hash char(64);
ALTER TABLE sigov.rh_vinculo_funcional ADD COLUMN IF NOT EXISTS matricula varchar(40);
ALTER TABLE sigov.rh_frequencia ADD COLUMN IF NOT EXISTS data_referencia date, ADD COLUMN IF NOT EXISTS tipo varchar(30);
ALTER TABLE sigov.folha_competencia ADD COLUMN IF NOT EXISTS competencia date;

CREATE UNIQUE INDEX IF NOT EXISTS ux_rh_servidor_cpf_ativo ON sigov.rh_servidor(tenant_id, cpf_hash) WHERE ativo AND cpf_hash IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS ux_rh_vinculo_matricula ON sigov.rh_vinculo_funcional(tenant_id, entidade_id, matricula) WHERE matricula IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS ux_rh_frequencia_lancamento ON sigov.rh_frequencia(tenant_id, servidor_id, data_referencia, tipo) WHERE data_referencia IS NOT NULL AND tipo IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS ux_folha_competencia_contexto ON sigov.folha_competencia(tenant_id, entidade_id, competencia, orgao_id, unidade_gestora_id, unidade_executora_id) WHERE competencia IS NOT NULL;
INSERT INTO sigov.permissao (modulo, chave, recurso, acao, descricao, ativo, is_deleted)
SELECT CASE WHEN p.chave LIKE 'FOLHA_%' THEN 'folha' WHEN p.chave LIKE 'PORTAL_%' THEN 'portal_servidor' ELSE 'rh' END, p.chave, 'rh360',
 CASE WHEN p.chave LIKE '%VIEW' OR p.chave LIKE '%ACCESS' THEN 'visualizar' WHEN p.chave LIKE '%EXPORT' THEN 'exportar' ELSE 'gerenciar' END, p.nome, true, false
FROM (VALUES ('RH_DASHBOARD_VIEW','Rh Dashboard View'),('RH_SERVIDOR_VIEW','Rh Servidor View'),('RH_SERVIDOR_MANAGE','Rh Servidor Manage'),('RH_DADO_SENSIVEL_VIEW','Rh Dado Sensivel View'),('RH_DADO_SENSIVEL_EXPORT','Rh Dado Sensivel Export'),('RH_CARGO_MANAGE','Rh Cargo Manage'),('RH_LOTACAO_MANAGE','Rh Lotacao Manage'),('RH_ATO_VIEW','Rh Ato View'),('RH_ATO_MANAGE','Rh Ato Manage'),('RH_FREQUENCIA_VIEW','Rh Frequencia View'),('RH_FREQUENCIA_MANAGE','Rh Frequencia Manage'),('RH_FERIAS_MANAGE','Rh Ferias Manage'),('RH_LICENCA_MANAGE','Rh Licenca Manage'),('RH_AFASTAMENTO_MANAGE','Rh Afastamento Manage'),('FOLHA_DASHBOARD_VIEW','Folha Dashboard View'),('FOLHA_EVENTO_MANAGE','Folha Evento Manage'),('FOLHA_CALCULAR','Folha Calcular'),('FOLHA_FECHAR','Folha Fechar'),('FOLHA_REABRIR','Folha Reabrir'),('FOLHA_CONTRACHEQUE_VIEW','Folha Contracheque View'),('FOLHA_RELATORIO_EXPORT','Folha Relatorio Export'),('PORTAL_SERVIDOR_ACCESS','Portal Servidor Access'),('PORTAL_SERVIDOR_REQUERIMENTO_CREATE','Portal Servidor Requerimento Create'),('RH_ESOCIAL_VIEW','Rh Esocial View'),('RH_ESOCIAL_MANAGE','Rh Esocial Manage')) p(chave,nome) WHERE NOT EXISTS (SELECT 1 FROM sigov.permissao x WHERE x.chave=p.chave);

